for (auto it = tri.triangulation.finite_cells_begin(); it != tri.triangulation.finite_cells_end(); ++it) {
    Tetrahedron t;
    // A tetrahedron is defined by 4 points
    // In CGAL, a cell stores 4 vertices (in 3D)
    // We extract the points from the 4 vertices of each cell
    const auto& cell = *it;

    // Extract the 4 vertices of the tetrahedron
    // In CGAL, vertices are accessed via vertex(i) for i in 0,1,2,3
    // The vertices of a cell in CGAL are indexed from 0 to 3
    t[0] = Point3d(
        CGAL::to_double(cell.vertex(0)->point().x()),
        CGAL::to_double(cell.vertex(0)->point().y()),
        CGAL::to_double(cell.vertex(0)->point().z())
    );
    t[1] = Point3d(
        CGAL::to_double(cell.vertex(1)->point().x()),
        CGAL::to_double(cell.vertex(1)->point().y()),
        CGAL::to_double(cell.vertex(1)->point().z())
    );
    t[2] = Point3d(
        CGAL::to_double(cell.vertex(2)->point().x()),
        CGAL::to_double(cell.vertex(2)->point().y()),
        CGAL::to_double(cell.vertex(2)->point().z())
    );
